export interface ConnectorConfig {
  /** Brevo API key from environment variable BREVO_API_KEY */
  brevoApiKey: string
  /** Numeric Brevo list ID to subscribe the contact to */
  brevoListId: number
  /** Typeform field IDs for mapping answers to contact fields */
  typeformFieldIds: {
    /** Field ID for the email answer */
    emailFieldId: string
    /** Field ID for the first name answer */
    firstNameFieldId: string
    /** Field ID for the last name answer */
    lastNameFieldId: string
  }
  /** Allow updating existing contacts (default: false) */
  updateEnabled?: boolean
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
      }
    }>
  }
}

export interface HandleResult {
  contactId: number
  email: string
}

function getAnswerValue(answers: TypeformWebhookPayload['form_response']['answers'], fieldId: string): string | undefined {
  const answer = answers.find((a) => a.field.id === fieldId)
  if (!answer) return undefined
  if (answer.type === 'email') return answer.email
  if (answer.type === 'text') return answer.text
  return undefined
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.form_response?.answers?.length) {
    throw new Error('Missing required field: form_response.answers')
  }

  const { emailFieldId, firstNameFieldId, lastNameFieldId } = config.typeformFieldIds

  const email = getAnswerValue(payload.form_response.answers, emailFieldId)
  if (!email) {
    throw new Error(`Missing required field: email (field ID ${emailFieldId})`)
  }

  const firstName = getAnswerValue(payload.form_response.answers, firstNameFieldId) ?? ''
  const lastName = getAnswerValue(payload.form_response.answers, lastNameFieldId) ?? ''

  const body = {
    email,
    attributes: {
      FNAME: firstName,
      LNAME: lastName,
    },
    listIds: [config.brevoListId],
    updateEnabled: config.updateEnabled ?? false,
    ext_id: payload.form_response.token,
  }

  const response = await fetchImpl('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': config.brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Brevo API error: ${response.status} ${response.statusText} for POST https://api.brevo.com/v3/contacts - ${text}`)
  }

  const data = (await response.json()) as { id: number }
  return { contactId: data.id, email }
}

