    headers: {
      'api-key': config.brevoApiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Brevo API error: ${response.status} ${response.statusText} for POST https://api.brevo.com/v3/contacts - ${text}`)
  }

  // Handle 204 No Content and other empty-body responses gracefully
  const responseText = await response.text()
  let contactId: number
  if (responseText) {
    const data = JSON.parse(responseText) as { id: number }
    contactId = data.id
  } else {
    // For 204 No Content, we can't get the ID from response
    // This shouldn't happen with Brevo's POST /v3/contacts which returns 201 with ID
    throw new Error('Brevo API returned success but with empty response body')
  }

  return { contactId, email }
}

